// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {W_WALLET, Log} from "../src/W_WALLET.sol";

contract InvMutTest is Test {
    W_WALLET c;
    function setUp() public { c = new W_WALLET(address(new Log())); }

    function testFuzz_property(uint256 amount, uint256 unlockTime, address actor) public {
        vm.assume(actor != address(0) && actor != address(c) && actor != address(this));
        amount = bound(amount, 1, 1000 ether);
        unlockTime = bound(unlockTime, 0, block.timestamp); // an unlock time in the past (or exactly now)

        vm.deal(actor, amount);
        vm.prank(actor);
        c.Put{value: amount}(unlockTime);

        (uint256 unlockStored, ) = c.Acc(actor);
        assertTrue(unlockStored >= block.timestamp); // correct C clamps past times to now; mutant stores past time
    }
}
